import "dotenv/config";
import { isAbsolute, resolve } from "node:path";
import { defineConfig } from "prisma/config";

const configuredUrl = process.env.DATABASE_URL ?? "file:./dev.db";
const configuredPath = configuredUrl.slice("file:".length);
const databaseUrl = configuredUrl.startsWith("file:")
  ? `file:${isAbsolute(configuredPath) ? configuredPath : resolve(process.cwd(), "prisma", configuredPath)}`
  : configuredUrl;

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: databaseUrl,
  },
});
